package com.shale.data.dao;

import static org.junit.jupiter.api.Assertions.*;
import static com.shale.core.service.OrganizationServicePort.*;
import java.lang.reflect.Proxy;
import java.sql.*;
import java.util.*;
import org.junit.jupiter.api.Test;

/** Behavioral transaction proof for the connection-owning Organization aggregate. */
final class OrganizationAggregateTransactionTest {
	@Test void legacySingleTypeCreateCommitsOrganizationPrimaryAssignmentCompatibilityAndAuditTogether(){
		var db=new FakeDb(null);int id=new OrganizationDao(db).create(new OrganizationDao.OrganizationCreateRequest(7,12,"Org",null,null,null,null,null,null,null,null,null,null,null));
		assertEquals(42,id);assertEquals(List.of("begin","organization:12","assignment:12:true:0","audit","audit","commit","restore-auto","close"),db.events);
	}
	@Test void multipleAssignmentsCommitWithExactlyOnePrimary(){var db=new FakeDb(null);var dao=new OrganizationTypeMutationDao(db);int id=dao.createAggregate(new CreateOrganizationAggregateCommand(7,9,new OrganizationFields("Org",null,null,null,null,null,null,null,null,null,null,null),List.of(new StagedOrganizationTypeAssignment(null,12,true,0,null),new StagedOrganizationTypeAssignment(null,13,false,1,null))));assertEquals(42,id);assertEquals(2,db.events.stream().filter(e->e.startsWith("assignment:")).count());assertEquals(1,db.events.stream().filter(e->e.contains(":true:")).count());assertTrue(db.events.contains("commit"));}
	@Test void assignmentOrAuditFailureRollsBackOrganizationAndAllAssignments(){for(String failure:List.of("assignment","audit")){var db=new FakeDb(failure);var dao=new OrganizationTypeMutationDao(db);assertThrows(RuntimeException.class,()->dao.createAggregate(new CreateOrganizationAggregateCommand(7,9,new OrganizationFields("Org",null,null,null,null,null,null,null,null,null,null,null),List.of(new StagedOrganizationTypeAssignment(null,12,true,0,null)))));assertTrue(db.events.contains("rollback"),failure);assertFalse(db.events.contains("commit"),failure);}}
	@Test void zeroOrMultiplePrimariesFailBeforeOpeningTransaction(){for(var assignments:List.of(List.of(new StagedOrganizationTypeAssignment(null,12,false,0,null)),List.of(new StagedOrganizationTypeAssignment(null,12,true,0,null),new StagedOrganizationTypeAssignment(null,13,true,1,null)))){var db=new FakeDb(null);assertThrows(IllegalArgumentException.class,()->new OrganizationTypeMutationDao(db).createAggregate(new CreateOrganizationAggregateCommand(7,9,new OrganizationFields("Org",null,null,null,null,null,null,null,null,null,null,null),assignments)));assertTrue(db.events.isEmpty());}}

	private static final class FakeDb implements com.shale.core.runtime.DbSessionProvider {final List<String> events=new ArrayList<>();final String failure;FakeDb(String f){failure=f;}public Connection requireConnection(){return connection();}
		private Connection connection(){return (Connection)Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class[]{Connection.class},(p,m,a)->switch(m.getName()){case"getAutoCommit"->true;case"setAutoCommit"->{events.add((boolean)a[0]?"restore-auto":"begin");yield null;}case"prepareStatement"->statement((String)a[0]);case"commit","rollback","close"->{events.add(m.getName());yield null;}case"isClosed"->false;default->defaultValue(m.getReturnType());});}
		private PreparedStatement statement(String sql){Map<Integer,Object>b=new HashMap<>();return(PreparedStatement)Proxy.newProxyInstance(PreparedStatement.class.getClassLoader(),new Class[]{PreparedStatement.class},(p,m,a)->switch(m.getName()){case"setInt","setLong","setString","setBoolean","setBytes","setNull"->{b.put((Integer)a[0],a.length>1?a[1]:null);yield null;}case"executeQuery"->{if(sql.contains("SESSION_CONTEXT(N'ShaleClientId')"))yield rows(new Object[][]{{7}});if(sql.contains("SESSION_CONTEXT(N'PrincipalUserId')"))yield rows(new Object[][]{{9}});if(sql.contains("FROM dbo.Users"))yield rows(new Object[][]{{1}});if(sql.contains("FROM dbo.OrganizationTypes WHERE OrganizationTypeId"))yield rows(new Object[][]{{b.get(1),7,"type",true,false,new byte[]{1}}});if(sql.contains("OUTPUT INSERTED.Id")&&sql.contains("dbo.Organizations")){events.add("organization:"+b.get(2));yield rows(new Object[][]{{42}});}if(sql.contains("OUTPUT INSERTED.Id")&&sql.contains("OrganizationOrganizationTypes")){events.add("assignment:"+b.get(3)+":"+b.get(4)+":"+b.get(5));if("assignment".equals(failure))throw new SQLException("assignment failed");yield rows(new Object[][]{{100L}});}if(sql.contains("SELECT Id,OrganizationId,OrganizationTypeId"))yield rows(new Object[][]{{100L,42,b.getOrDefault(1,12),true,0,false,new byte[]{2}}});throw new SQLException("Unexpected query: "+sql);}case"executeUpdate"->{if(sql.contains("EntityActionAuditLog")){events.add("audit");if("audit".equals(failure))throw new SQLException("audit failed");}yield 1;}case"close"->null;default->defaultValue(m.getReturnType());});}
	}
	private static ResultSet rows(Object[][] rows){int[] i={-1};return(ResultSet)Proxy.newProxyInstance(ResultSet.class.getClassLoader(),new Class[]{ResultSet.class},(p,m,a)->switch(m.getName()){case"next"->++i[0]<rows.length;case"getObject"->rows[i[0]][((Integer)a[0])-1];case"getInt"->((Number)rows[i[0]][((Integer)a[0])-1]).intValue();case"getLong"->((Number)rows[i[0]][((Integer)a[0])-1]).longValue();case"getString"->String.valueOf(rows[i[0]][((Integer)a[0])-1]);case"getBoolean"->(Boolean)rows[i[0]][((Integer)a[0])-1];case"getBytes"->(byte[])rows[i[0]][((Integer)a[0])-1];case"close"->null;default->defaultValue(m.getReturnType());});}
	private static Object defaultValue(Class<?> c){if(!c.isPrimitive())return null;if(c==boolean.class)return false;if(c==int.class)return 0;if(c==long.class)return 0L;return null;}
}
